import subprocess
import os
import time
import glob

def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    """
    Executes an R script and verifies if the output file is generated within a given duration.
    """
    # Start the R script process
    # We use shell=True or specify 'Rscript' as the command
    process = subprocess.Popen(['Rscript', r_script_path], 
                               stdout=subprocess.PIPE, 
                               stderr=subprocess.PIPE)

    start_time = time.time()

    # Poll for the file existence until the duration is reached
    while time.time() - start_time < duration:
        if os.path.exists(output_path):
            # Optional: terminate the process if it's still running after file creation
            if process.poll() is None:
                process.terminate()
            return (True, 'File generated successfully within the specified duration.')

        # Check if the process finished prematurely
        if process.poll() is not None:
            break

        time.sleep(1)  # Wait 1 second before checking again

    # Final check after loop
    if os.path.exists(output_path):
        return (True, 'File generated successfully within the specified duration.')
    else:
        # Ensure process is killed if it timed out
        if process.poll() is None:
            process.terminate()
        return (False, 'File not generated within the specified duration.')

import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    """
    Compresses all files in the source folder using gzip and moves them to the destination folder.
    Runs as a background process for each file.
    """
    result = {
        'success': True,
        'message': '',
        'failed_files': []
    }

    # Ensure destination exists
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {'success': False, 'message': f"Could not create destination folder: {str(e)}", 'failed_files': []}

    # Get all files in source folder
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]

    if not files:
        return {'success': True, 'message': "No files found to compress.", 'failed_files': []}

    processes = []

    # Start gzip processes for each file
    for file_path in files:
        try:
            # gzip -c outputs to stdout, we redirect to the destination path
            filename = os.path.basename(file_path)
            dest_path = os.path.join(dst_folder, f"{filename}.gz")

            # Open file for reading and destination for writing
            with open(file_path, 'rb') as f_in:
                with open(dest_path, 'wb') as f_out:
                    # Using subprocess to run gzip as a background process
                    p = subprocess.Popen(['gzip', '-c'], stdin=f_in, stdout=f_out)
                    processes.append((p, file_path))
        except Exception:
            result['failed_files'].append(os.path.basename(file_path))

    # Wait for all processes to complete
    for p, original_path in processes:
        p.wait()
        if p.returncode != 0:
            result['failed_files'].append(os.path.basename(original_path))
        else:
            # Remove original file after successful compression
            try:
                os.remove(original_path)
            except OSError:
                result['failed_files'].append(os.path.basename(original_path))

    if result['failed_files']:
        result['success'] = False
        result['message'] = f"Operation completed with {len(result['failed_files'])} errors."
    else:
        result['message'] = "All files compressed and moved successfully."

    return result
